We now prove \eqref{e:incodom2}; we also discuss how the set $\mathsf{CH}^{\scriptscriptstyle\complement}$ depends on the thresholds $q_*^-$ and $q_*^+$.
First, by \eqref{e:incodom1}, \eqref{e:hc} and \eqref{e:qc} we notice that 
\[\mathsf{CH}^{\scriptscriptstyle\complement}(q_*^-,q_*^+) = \left( \mathsf{CH}^{\scriptscriptstyle\complement}_{1}(q_*^-,q_*^+) \cup \mathsf{CH}^{\scriptscriptstyle\complement}_{2}(q_*^-) \right) \cap \mathsf{CH}^{\scriptscriptstyle\complement}_{3}(q_*^+),\]
where
\begin{subequations}
\label{e:CH123}
\begin{align}
\label{e:CH1}
\mathsf{CH}^{\scriptscriptstyle\complement}_{1}(q_*^-,q_*^+) & \doteq \left\{ (u_\ell,u_r,h_o)\in\mathsf{D}\times\{0\} : \overline{Q}\left(u_\ell\right) \in [q_*^-,q_*^+] \right\},
\\
\label{e:CH2}
\mathsf{CH}^{\scriptscriptstyle\complement}_{2}(q_*^-) & \doteq \left\{ (u_\ell,u_r,h_o)\in\mathsf{D}\times\{0,1\} : \overline{Q}\left(u_\ell\right) < q_*^- \right\},
\\
\label{e:CH3}
\mathsf{CH}^{\scriptscriptstyle\complement}_{3}(q_{*}^{+}) & \doteq \left\{ (u_\ell,u_r,h_o)\in\mathsf{D}\times\{0,1\} : \overline{Q}\left(\hat{u}(0,u_{\ell})\right) > q_{*}^{+} \right\}.
\end{align}
\end{subequations}
Observe that $\mathsf{CH}^{\scriptscriptstyle\complement}_{1}(q_*^-,q_*^+) \cup \mathsf{CH}^{\scriptscriptstyle\complement}_{2}(q_*^-) = \left\{ (u_\ell,u_r,h_o)\in\mathsf{D}\times\{0,1\} : q_{\rm c}^{0}(u_\ell,h_o) = 0 \right\}$.
We also have
\begin{align*}
[q_{*\alpha}^-,q_{*\alpha}^+] \subseteq [q_{*\beta}^-,q_{*\beta}^+]
&\Longrightarrow
\mathsf{CH}^{\scriptscriptstyle\complement}_{1}(q_{*\alpha}^-,q_{*\alpha}^+) \subseteq \mathsf{CH}^{\scriptscriptstyle\complement}_{1}(q_{*\beta}^-,q_{*\beta}^+),
\\
q_{*\alpha}^{-} \leqslant q_{*\beta}^{-}
&\Longrightarrow
\mathsf{CH}^{\scriptscriptstyle\complement}_{2}(q_{*\alpha}^-) \subseteq \mathsf{CH}^{\scriptscriptstyle\complement}_{2}(q_{*\beta}^-).
\end{align*}

Roughly speaking, $\mathsf{CH}^{\scriptscriptstyle\complement}_{1}(q_*^-,q_*^+)$, $\mathsf{CH}^{\scriptscriptstyle\complement}_{2}(q_*^-)$ and $\mathsf{CH}^{\scriptscriptstyle\complement}_{3}(q_*^+)$ can be represented as in \figurename~\ref{f:CH123}, and $\mathsf{CH}^{\scriptscriptstyle\complement}(q_*^-,q_*^+)$ as in \figurename~\ref{f:CH}.
More precisely, let $\pi_{\ell} \colon \mathsf{D} \times \{0,1\} \to \Omega$ denote the projection onto the first $u$-component, namely
\[
\pi_{\ell}\left(u_{\ell},u_{r},h_{o}\right) = u_{\ell}.
\]
Then in \figurename~\ref{f:CH123} we represent $\pi_{\ell}\left(\mathsf{CH}^{\scriptscriptstyle\complement}_{1}(q_*^-,q_*^+)\right)$, $\pi_{\ell}\left(\mathsf{CH}^{\scriptscriptstyle\complement}_{2}(q_*^-)\right)$ and $\pi_{\ell}\left(\mathsf{CH}^{\scriptscriptstyle\complement}_{3}(q_*^+)\right)$, while for $\pi_{\ell}\left(\mathsf{CH}^{\scriptscriptstyle\complement}(q_*^-,q_*^+)\right)$ see \figurename~\ref{f:CH}.

